import sys

def calculate(s):
    length = len(s)
    p = 1 if s[0] != '0' else 0
    for i in range(length - 2):
        if s[i] == '_':
            p *= 9 if i == 0 else 10
    p1 = 0
    if s[-1] == '_' and s[-2] == '_':
        p1 = 3 if length == 2 else 4
    elif s[-1] == '_':
        if s[-2] in '0527':
            p1 = 1
    elif s[-2] == '_':
        if s[-1] == '0':
            p1 = 1 if length == 2 else 2
        elif s[-1] == '5':
            p1 = 2
    else:
        val = int(s[-2:])
        if val % 25 == 0:
            p1 = 1
    return p * p1

def main():
    s = sys.stdin.readline().strip()
    T = 1
    while T > 0:
        if len(s) == 1:
            if s in "0_X":
                print(1)
            else:
                print(0)
        else:
            foundX = 'X' in s
            if not foundX:
                print(calculate(s))
            else:
                totalSum = 0
                for d in range(10):
                    replaced = s.replace('X', str(d))
                    totalSum += calculate(replaced)
                print(totalSum)
        T -= 1

if __name__ == "__main__":
    main()

